-- Surplus-to-Shelter core schema, RLS, and atomic operations.
create type public.user_role as enum ('DONOR','NGO','DRIVER','ADMIN'); create type public.donation_status as enum ('POSTED','MATCHING','OFFERED','MATCHED','PICKUP_ACCEPTED','PICKED_UP','IN_TRANSIT','DELIVERED','EXPIRED','CANCELLED','NOT_FEASIBLE'); create type public.match_status as enum ('OFFERED','VIEWED','ACCEPTED','DECLINED','EXPIRED','CANCELLED','CLOSED'); create type public.pickup_status as enum ('OFFERED','ACCEPTED','DECLINED','PICKED_UP','IN_TRANSIT','DELIVERED','CANCELLED');
create table public.profiles(id uuid primary key references auth.users on delete cascade,name text not null,email text not null,phone text,role user_role not null default 'DONOR',avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles(id) on delete set null,name text not null,type text not null check(type in ('DONOR','SHELTER')),address text not null,latitude numeric not null check(latitude between -90 and 90),longitude numeric not null check(longitude between -180 and 180),phone text,email text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.shelter_profiles(organization_id uuid primary key references public.organizations(id) on delete cascade,max_capacity_kg numeric not null check(max_capacity_kg>=0),current_capacity_kg numeric not null default 0 check(current_capacity_kg>=0 and current_capacity_kg<=max_capacity_kg),accepted_food_types text[] not null default '{}',needed_food_types text[] not null default '{}',is_accepting boolean not null default true,operating_hours text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.drivers(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references public.profiles(id) on delete cascade,name text not null,phone text,latitude numeric,longitude numeric,is_available boolean not null default true,vehicle_type text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.donations(id uuid primary key default gen_random_uuid(),donor_id uuid not null references public.profiles(id) on delete restrict,food_name text not null,category text not null,quantity numeric not null check(quantity>0),unit text not null default 'kg',pickup_address text not null,pickup_latitude numeric not null,pickup_longitude numeric not null,available_from timestamptz not null default now(),expires_at timestamptz not null check(expires_at>available_from),notes text,image_url text,status donation_status not null default 'POSTED',matched_shelter_id uuid references public.organizations(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.donation_matches(id uuid primary key default gen_random_uuid(),donation_id uuid not null references public.donations(id) on delete cascade,shelter_id uuid not null references public.organizations(id) on delete cascade,distance_km numeric not null,estimated_travel_minutes integer not null,match_score numeric not null,capacity_ok boolean not null,food_need_ok boolean not null,time_feasible boolean not null,driver_available boolean not null,status match_status not null default 'OFFERED',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(donation_id,shelter_id));
create table public.pickup_requests(id uuid primary key default gen_random_uuid(),donation_id uuid unique not null references public.donations(id) on delete cascade,driver_id uuid not null references public.drivers(id) on delete restrict,donor_id uuid not null references public.profiles(id) on delete restrict,shelter_id uuid not null references public.organizations(id) on delete restrict,driver_to_donor_minutes integer not null,donor_to_shelter_minutes integer not null,total_estimated_minutes integer not null,status pickup_status not null default 'OFFERED',assigned_at timestamptz not null default now(),accepted_at timestamptz,picked_up_at timestamptz,delivered_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,donation_id uuid references public.donations(id) on delete cascade,type text not null,title text not null,message text not null,metadata jsonb not null default '{}',is_read boolean not null default false,created_at timestamptz not null default now()); create table public.impact_records(id uuid primary key default gen_random_uuid(),donation_id uuid unique not null references public.donations(id) on delete cascade,quantity_kg numeric not null,estimated_meals numeric not null,estimated_co2e_avoided numeric not null,delivered_at timestamptz not null default now(),created_at timestamptz not null default now());
create index donations_donor_status_idx on public.donations(donor_id,status); create index matches_shelter_status_idx on public.donation_matches(shelter_id,status); create index notifications_user_idx on public.notifications(user_id,is_read);
create or replace function public.claim_donation(p_match uuid) returns public.donations language plpgsql security definer set search_path=public as $$ declare m donation_matches; d donations; begin select * into m from donation_matches where id=p_match for update; select * into d from donations where id=m.donation_id for update; if m.status not in ('OFFERED','VIEWED') or d.status not in ('OFFERED','MATCHING') or d.expires_at<=now() then raise exception 'This donation has already been claimed.'; end if; if not exists(select 1 from shelter_profiles where organization_id=m.shelter_id and is_accepting and max_capacity_kg-current_capacity_kg>=d.quantity) then raise exception 'Shelter capacity or availability changed.'; end if; update donations set status='MATCHED',matched_shelter_id=m.shelter_id where id=d.id; update donation_matches set status=case when id=m.id then 'ACCEPTED' else 'CLOSED' end where donation_id=d.id; update shelter_profiles set current_capacity_kg=current_capacity_kg+d.quantity where organization_id=m.shelter_id; return (select * from donations where id=d.id); end $$;
alter table public.profiles enable row level security; alter table public.donations enable row level security; alter table public.donation_matches enable row level security; alter table public.notifications enable row level security; create policy "own profile" on profiles for all using(id=auth.uid()) with check(id=auth.uid()); create policy "donor donations" on donations for all using(donor_id=auth.uid() or (select role from profiles where id=auth.uid())='ADMIN') with check(donor_id=auth.uid()); create policy "notifications own" on notifications for select using(user_id=auth.uid());
